      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402202,
      role5 = 4118401,
      sentence = "Gavin stood me back up, and the hand over my waist was duly withdrawn. He had just finished a fight, and his burning eyes looked playfully at me.",
