      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402202,
      role5 = 4118401,
      sentence = "He brought up those days of old at Grandletter Academy, with that same old tone of voice, but I didn't dare touch those wonderful memories in his presence, so I hastily changed the topic.",
      next = {52}
