      music = "73_After_the_FutureA",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118107,
      role3 = 402206,
      role5 = 4118401,
      sentence = "As soon as I spoke, the warmth beside me subsided noticeably. A moment later, Gavin spoke up once again.",
