    [55] = {
      beijing = 2022,
      dialog = 3,
      music = "73_After_the_FutureA",
      renwu = "npc",
      sentence = "With that said, he turned and left. With the sudden absence beside me, the cold wind seeped into my clothes, causing me to shiver.",
