      renming = "Gavin",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118107,
      role3 = 402206,
      role5 = 4118401,
      sentence = "The Rongdi are hunkered down in Redtower, and no matter how we try to bait them out, they won't bite. If we keep wasting time like this, we'll never take the city.",
      voice = 2,
      next = {61}
    },
    [61] = {
      beijing = 4497,
      dialog = 3,
      music = "85_Spring_SP",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118107,
      role3 = 402206,
      role5 = 4118401,
      sentence = "He placed the flag in his hand in where Redtower's rear guard was — Camp Glacier.",
      next = {62}
    },
    [62] = {
