      renming = "Gavin",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118107,
      role3 = 402206,
      role5 = 4118401,
      sentence = "Since it's so easily defendable, we'll just have to take it by storm. I'll lead a squad of light cavalry to raid Camp Glacier. The light cavalry will serve as a diversion, drawing the enemy army out of the camp.",
      voice = 2,
      next = {63}
    },
    [63] = {
