    [68] = {
      beijing = 4497,
      dialog = 3,
      music = "85_Spring_SP",
      renwu = "npc",
      sentence = "At the mention of the Battle of Jade Gate, I saw the faces of the generals suddenly change, and the temperature in the tent plummeted a few more degrees.",
