      dialog = 1,
      music = "85_Spring_SP",
      renming = "$u",
      renwu = "npc",
      sentence = "Two years ago, Camp Sparrow's provisions were looted, and our forward camp was unable to strike back, and fifty thousand soldiers died tragically on Redmoon Dunes.",
