      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      ruchang = -1,
      sentence = "As I cast an earnest glance at Gavin, the flickering fire light danced on his face. He looked at me with an icy, dire look that I'd rarely seen.",
